#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>

#define LED_PIN 17 // Replace with the pin number of your LED

int main() {
    int fd;
    char buffer[1];

    // Open the GPIO device file
    fd = open("/dev/gpiochip0", O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    // Set the LED pin as an output
    ioctl(fd, IOCTL_GPIO_DIRECTION_OUTPUT, &LED_PIN);

    // Initialize the LED to be off
    ioctl(fd, IOCTL_GPIO_WRITE, &LED_PIN, 0);

    while (1) {
        // Turn the LED on
        ioctl(fd, IOCTL_GPIO_WRITE, &LED_PIN, 1);
        usleep(500000); // Blink at 2 Hz

        // Turn the LED off
        ioctl(fd, IOCTL_GPIO_WRITE, &LED_PIN, 0);
        usleep(500000); // Blink at 2 Hz
    }

    // Clean up
    close(fd);
    return 0;
}
```
