    :param dt_node: The Device Tree node containing the `reg` and `reg-names` properties.
    :param address: The IOMEM address to parse.
    :return: The corresponding memory region name (or None if not found).
    """
    regs = dt_node.get('reg')
    reg_names = dt_node.get('reg-names')

    if not regs or not reg_names:
