// функция для вычисления интеграла методом прямоугольников
double integrateRectangle(double f(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += f(a + i * h);
    }
    return sum * h;
}

// функция для вычисления интеграла методом трапеций
double integrateTrapezoid(double f(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += f(a + i * h) + f(a + (i + 1) * h);
    }
    return sum * h / 2;
}

// функция для вычисления интеграла методом Симпсона
double integrateSimpson(double f(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += f(a + i * h) + 4 * f(a + (i + 1) * h) + f(a + (i + 2) * h);
    }
    return sum * h / 3;
}

// поток для вычисления интеграла
DWORD WINAPI integrateThread(LPVOID lpParameter) {
    struct {
        double (*f)(double);
        double a, b;
        int n;
    } *params = (struct {} *)lpParameter;

    double result = 0;
    HANDLE mutex = CreateMutex(NULL, FALSE, NULL);
    WaitForSingleObject(mutex, INFINITE);

    if (params->f == &sin) {
        result = integrateRectangle(sin, params->a, params->b, params->n);
    } else if (params->f == &cos) {
        result = integrateTrapezoid(cos, params->a, params->b, params->n);
    } else {
        result = integrateSimpson(tan, params->a, params->b, params->n);
    }

    ReleaseMutex(mutex);

    return 0;
}

int main() {
    // инициализация мьютекса
    HANDLE mutex = CreateMutex(NULL, FALSE, NULL);

    // инициализация семафора
    HANDLE semaphore = CreateSemaphore(NULL, 0, 100, NULL);

    // создание потоков
    std::vector<HANDLE> threads;
    for (int i = 0; i < 5; i++) {
        threads.push_back(CreateThread(NULL, 0, integrateThread, new struct {
            double (*f)(double);
            double a, b;
            int n;
        }{
            sin, 0, 1, 1000 // любое начальное значение
        }, 0, NULL));
    }

    // ожидание завершения вычислений всеми потоками
    for (auto thread : threads) {
        WaitForSingleObject(thread, INFINITE);
        ReleaseSemaphore(semaphore, 1, NULL);
    }

    // получение результатов вычислений
    double result = 0;
    WaitForSingleObject(mutex, INFINITE);
    for (int i = 0; i < 5; i++) {
        result += result;
    }
    ReleaseMutex(mutex);

    std::cout << "Result: " << result << std::endl;

    // очистка ресурсов
    for (auto thread : threads) {
        CloseHandle(thread);
    }
    CloseHandle(mutex);
    CloseHandle(semaphore);

    return 0;
}
```
